def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Parameters:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # Ensure all 26 letters are present in the mapping (bijective mapping)
    if len(mapping) != 26:
        return "Failed"
    if len(set(mapping.values())) != 26:
        return "Failed"

    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstruct a binary tree from its inorder and postorder traversal strings
    and return the preorder traversal as a string.
    """
    try:
        if len(inorder) != len(postorder):
            raise ValueError("inorder and postorder must have the same length")
        if not inorder:
            return ""
        # Build hash for quick lookup of inorder indices
        index_map = {ch: i for i, ch in enumerate(inorder)}
        if set(inorder) != set(postorder):
            raise ValueError("inorder and postorder must contain the same characters")
        def helper(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
            if in_left > in_right or post_left > post_right:
                return ""
            root = postorder[post_right]
            in_root_idx = index_map[root]
            left_size = in_root_idx - in_left
            left_pre = helper(in_left, in_root_idx - 1, post_left, post_left + left_size - 1)
            right_pre = helper(in_root_idx + 1, in_right, post_left + left_size, post_right - 1)
            return root + left_pre + right_pre
        return helper(0, len(inorder) - 1, 0, len(postorder) - 1)
    except Exception as e:
        raise ValueError(f"Error processing traversal strings: {e}") from e

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers reachable from the original integer `n` by applying the provided
    digit transformation rules. Each rule is a tuple (x, y) indicating that digit `x` can be
    transformed into digit `y`. A breadth‑first search explores all possible transformations.
    The returned value is the count of unique numbers, including the original number.

    Args:
        n: The original integer number to transform.
        rules: A list of tuples (x, y) with single‑digit integers (0‑9).

    Returns:
        The total count of unique numbers that can be generated.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")

    queue = [n]
    visited = {n}

    while queue:
        current = queue.pop(0)
        current_str = str(current)

        for x, y in rules:
            # Ensure rule digits are single digits
            if not (isinstance(x, int) and isinstance(y, int) and 0 <= x <= 9 and 0 <= y <= 9):
                continue
            x_char = str(x)
            y_char = str(y)

            for idx, ch in enumerate(current_str):
                if ch == x_char:
                    # Replace only this occurrence
                    new_str = current_str[:idx] + y_char + current_str[idx + 1:]
                    try:
                        new_num = int(new_str)
                    except ValueError:
                        continue
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    # Helper to evaluate the truth value of a statement about guilt.
    def evaluate(statement: str, speaker: str) -> bool | None:
        stmt = statement.strip()
        # Ignore statements that are exactly a day of the week (case-insensitive).
        if stmt.upper() in (day.upper() for day in days_of_week):
            return None

        # Normalize to lower case for pattern matching.
        low = stmt.lower()

        # "I am guilty."
        if re.fullmatch(r"i\s+am\s+guilty\.?", low):
            return speaker == scenario

        # "<NAME> is guilty."
        m = re.fullmatch(r"([a-z]+)\s+is\s+guilty\.?", low)
        if m:
            subject = m.group(1).upper()
            return subject == scenario

        # "<NAME> is not guilty."
        m = re.fullmatch(r"([a-z]+)\s+is\s+not\s+guilty\.?", low)
        if m:
            subject = m.group(1).upper()
            return subject != scenario

        # Statement does not concern guilt; ignore it.
        return None

    # Iterate through all participants and their statements.
    for speaker, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate(stmt, speaker)
            if truth is None:
                # Non‑guilt statement or day statement – ignore.
                continue
            if speaker in liar_count:
                # Liars must always speak false statements.
                if truth:
                    return False
            else:
                # Truthful speakers must speak true statements.
                if not truth:
                    return False

    # If all statements satisfied the liar/truth constraints, the scenario is consistent.
    return True

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.
    """
    # Basic input validation
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")
    for idx, item in enumerate(student_scores):
        if not isinstance(item, (tuple, list)) or len(item) != 3:
            raise ValueError(f"Each element must be a tuple/list of length 3, got {item!r} at index {idx}")
        try:
            student_number, total_score, chinese_score = item
            if not (isinstance(student_number, int) and isinstance(total_score, (int, float)) and isinstance(chinese_score, (int, float))):
                raise ValueError
        except Exception:
            raise ValueError(f"Element at index {idx} contains non-numeric values: {item!r}")

    try:
        sorted_students = sorted(
            student_scores,
            key=lambda x: (-x[1], -x[2], x[0])
        )
    except Exception as e:
        raise RuntimeError(f"Error during sorting: {e}") from e

    return sorted_students
